double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    const int max_depth = 100;
    double c = (a + b) / 2.0;
    double full = (b - a) * (f(a) + f(b)) / 2.0;
    double left = (c - a) * (f(a) + f(c)) / 2.0;
    double right = (b - c) * (f(c) + f(b)) / 2.0;
    double combined = left + right;
    double error = std::abs(combined - full) / 3.0;

    if (error <= precision || max_depth == 0) {
        return combined;
    }

    return adaptive_trapezoidal(f, a, c, precision/2.0)
         + adaptive_trapezoidal(f, c, b, precision/2.0);
}
```

